oldid := sheet.Slot(1,2).id;
sheet := sheet.InsertAxis(2,2);
sheet[1,3] ##@ == 2;
sheet.Slot(1,3).id ##@ == oldid;
saved := .RiXCelExport(sheet);
.RiXCelImport(saved)[1,3] ##@ == 2;

