    .Paragraph([.Strong("Exact results"), 1/3]),
    .Table(["oriented interval"], [[5:4]])
]);
saved := .document.EncodeJSON(report);
imported := .document.DecodeJSON(saved);
.document.EncodeJSON(imported[:value]) == saved ##@ == 1;
imported[:diagnostics].Len() ##@ == 0;
